    def traffic_modify_stream(self, streams, attr_name_val, action="modify", traffic_apply=True):
        try:
            stream_list = self._trim_quotes_in_str(streams).split(",")
            input_handle_output = self._input_pattern_handling(streams)
            pattern_list_2 = input_handle_output[0]
            streams = input_handle_output[1]
            pattern_list_1 = [streams for streams in re.split(
                r',', streams) if streams]
            pattern_list_2 = list(pattern_list_2)
            stream_list = (pattern_list_1 + pattern_list_2)
            logger.info("pattern 1 is:{}".format(pattern_list_1))
            logger.info("pattern 2 is:{}".format(pattern_list_2))
            logger.info('Stream regexp passed - {0}'.format(stream_list))
            if action.lower() == 'modify':
                modify_attributes = dict(
                    list(map(str, attribute.strip().split(':', 1))) for attribute in attr_name_val.strip().split(","))
                logger.info('Attributes to be modified is {0}'.format(
                    modify_attributes))
                param_dict = dict()
                for attribute_name, attribute_value in modify_attributes.items():
                    attribute_value = attribute_value.replace("{", "").replace("}", "").replace(
                        "'", "")
                    logger.info(
                        "Attribute Val now is {}".format(attribute_value))
                    attribute_list = attribute_value.split()
                    logger.info(
                        "Attribute List now is {}".format(attribute_list))
                    if len(attribute_list) > 1:
                        # logic for modifying the stkSCVmRaw field that we get after decoding
                        # binary to python string
                        value_type_dict = dict()
                        value_type_dict['-fieldValue'] = attribute_list.pop(0)
                        value_type_dict.update(dict(
                            itertools.zip_longest(*[iter(attribute_list)] * 2, fillvalue="")))
                        value_type_dict = self._map_to_legacy_stream_attributes(
                            value_type_dict)
                        param_dict[attribute_name] = value_type_dict
                    else:
                        param_dict[attribute_name] = attribute_value
                    logger.info("Param dict is {}".format(param_dict))
            self.trex.traffic_modify_stream(stream_list, param_dict)
        except Exception as modify_error:
            raise Exception(
                "Modifying Streams failed due to  :{}".format(modify_error))

    def _map_to_legacy_stream_attributes(self, param_dict):
        """

        Args:
            param_dict: attributes to be modified

        Returns: mapped dict

        """
        for param_name, param_value in list(param_dict.items()):
            mapped_param_name = self.stream_variable_mapping.get(
                param_name) or param_name
            param_dict[mapped_param_name] = param_dict.pop(param_name)
        return param_dict

